     1	import { priceItems } from "./item-pricing.js";
     2	import type { Customer, Item } from "./policy.js";
     3	import {
     4	  customerStandingDiscount,
     5	  followUpContractDiscount,
     6	  initialAssessmentSurcharge,
     7	} from "./policy-modifier.js";
     8	
     9	const PROCESSING_FEE = 5;
    10	
    11	/**
    12	 * Item-specific modifiers apply to the base premium of the affected item;
    13	 * policy-wide modifiers apply to the policy base premium; the processing
    14	 * fee is added at the very end.
    15	 *
    16	 * Rounding is not an active behavior yet, so a premium may still come out
    17	 * as a fraction.
    18	 */
    19	export function quote(
    20	  customer: Customer,
    21	  items: readonly Item[],
    22	  previousContracts: number,
    23	): number {
    24	  const { basePremium, riskSurcharges } = priceItems(items);
    25	
    26	  return (
    27	    basePremium +
    28	    riskSurcharges +
    29	    initialAssessmentSurcharge(basePremium) -
    30	    customerStandingDiscount(customer, basePremium) -
    31	    followUpContractDiscount(previousContracts, basePremium) +
    32	    PROCESSING_FEE
    33	  );
    34	}
